#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Fatigue: fills in the GitHub `production` environment that .github/workflows/deploy-api.yml
# deploys the API from. See apps/api/README.md, "Deploying".
#
#   scripts/setup-production.sh
#
# Values go straight from your clipboard to GitHub with `gh`; nothing is written to disk.
# Re-running is safe: for anything already in GitHub, Enter keeps it.

REPO="AGroupForCoders/Fatigue"
ENVIRONMENT="production"
API_HOST="api.fatigue.agroupforcoders.com"   # matches routes in apps/api/wrangler.jsonc
BUCKET_DEFAULT="fatigue-media"
CF_API="https://api.cloudflare.com/client/v4"

# Nothing is saved locally, so there are no .env defaults to offer.
ENV_FILE="/nonexistent/fatigue-setup"

_EXISTING_SECRETS=""
_EXISTING_VARS=""

load_existing() {
  _EXISTING_SECRETS=$(gh secret list --repo "$REPO" --env "$ENVIRONMENT" --json name --jq '.[].name' 2>/dev/null || true)
  _EXISTING_VARS=$(gh variable list --repo "$REPO" --env "$ENVIRONMENT" --json name --jq '.[].name' 2>/dev/null || true)
}
has_secret() { grep -qx "$1" <<<"$_EXISTING_SECRETS"; }
has_var() { grep -qx "$1" <<<"$_EXISTING_VARS"; }
current_var() { gh variable get "$1" --repo "$REPO" --env "$ENVIRONMENT" 2>/dev/null || true; }

# env_secret NAME VALUE saves a secret in the production environment.
env_secret() {
  if printf '%s' "$2" | gh secret set "$1" --repo "$REPO" --env "$ENVIRONMENT" >/dev/null; then
    WRITTEN_SECRET+=("$1")
    printf '  %s✓ saved%s secret %s\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("secret $1: gh secret set $1 --repo $REPO --env $ENVIRONMENT")
    warn "couldn't save $1"
  fi
}

# env_var NAME VALUE saves a plain variable in the production environment.
env_var() {
  if gh variable set "$1" --repo "$REPO" --env "$ENVIRONMENT" --body "$2" >/dev/null; then
    WRITTEN_SECRET+=("$1 (variable)")
    printf '  %s✓ saved%s variable %s = %s\n' "$GREEN" "$RESET" "$1" "$2"
  else
    SKIPPED+=("variable $1: gh variable set $1 --repo $REPO --env $ENVIRONMENT --body '$2'")
    warn "couldn't save $1"
  fi
}

# secret_or_keep NAME "Prompt" asks for a secret, hidden. If GitHub already has it, Enter keeps it and
# $NAME comes back empty.
secret_or_keep() {
  local name="$1" prompt="$2" input=""
  if has_secret "$name"; then
    printf '  %s%s%s %s[already in GitHub; Enter keeps it]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  while [[ -z "$input" ]] && ! has_secret "$name"; do
    printf '  %sIt can'\''t be empty. %s%s ' "$YELLOW" "$prompt" "$RESET"
    read -rs input || true
    printf '\n'
  done
  printf -v "$name" '%s' "$input"
}

# cf_get PATH calls the Cloudflare API with the token, which never appears in the process list.
cf_get() {
  curl --silent --max-time 15 -H @<(printf 'Authorization: Bearer %s\n' "$CLOUDFLARE_API_TOKEN") "$CF_API$1"
}

# r2_status: HTTP status of listing the bucket with the R2 keys (200 means they work).
r2_status() {
  curl --silent --output /dev/null --write-out '%{http_code}' --max-time 15 --aws-sigv4 "aws:amz:auto:s3" \
    --config <(printf 'user = "%s:%s"\n' "$R2_ACCESS_KEY_ID" "$R2_SECRET_ACCESS_KEY") \
    "https://$CLOUDFLARE_ACCOUNT_ID.r2.cloudflarestorage.com/$R2_BUCKET?list-type=2&max-keys=1"
}

run_wizard() {

TOTAL_STAGES=10

banner "Fatigue production setup"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "GitHub: the production environment"
say "Every value ends up in the '$ENVIRONMENT' environment of $REPO,"
say "and each deploy copies them onto the Worker."
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "gh isn't installed or signed in. Run 'gh auth login', then run this again."
  exit 1
fi
for tool in curl jq openssl; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is needed. Install it and run this again."; exit 1; }
done
gh api --method PUT "repos/$REPO/environments/$ENVIRONMENT" --silent
load_existing
printf '  %s✓%s environment %s is ready\n' "$GREEN" "$RESET" "$ENVIRONMENT"
note "Already saved: $(echo $_EXISTING_SECRETS $_EXISTING_VARS | tr ' ' ',' | sed 's/,/, /g')"
pause

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Cloudflare: an API token for deploying"
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → 'Edit Cloudflare Workers' → Use template."
step "Account policy: Include → your account (leave its permissions as the template set them)."
step "Zone policy: Include → All zones from an account → your account."
step "Then make sure Developer Platform → Workers Routes → Edit is ticked (it serves $API_HOST)."
step "Continue to summary → Create Token → copy it (it's shown once)."
CLOUDFLARE_API_TOKEN=""
secret_or_keep CLOUDFLARE_API_TOKEN "Paste the token:"
if [[ -n "$CLOUDFLARE_API_TOKEN" ]]; then
  if [[ "$(cf_get /user/tokens/verify | jq -r '.result.status // empty')" == "active" ]]; then
    printf '  %s✓%s token works\n' "$GREEN" "$RESET"
  else
    warn "Cloudflare didn't accept that token. Check it was copied whole."
    confirm "Save it anyway?" || exit 1
  fi
  env_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
else
  note "Keeping the token in GitHub. The next stage asks for things the token would have looked up."
fi
pause

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Cloudflare: account and API address"
CLOUDFLARE_ACCOUNT_ID=""
if [[ -n "$CLOUDFLARE_API_TOKEN" ]]; then
  accounts=$(cf_get /accounts | jq -r '.result[]? | "\(.id)  \(.name)"')
  if [[ $(grep -c . <<<"$accounts") -eq 1 ]]; then
    CLOUDFLARE_ACCOUNT_ID=$(awk '{print $1}' <<<"$accounts")
    say "Account: $accounts"
  elif [[ -n "$accounts" ]]; then
    say "The token can see these accounts:"
    while IFS= read -r line; do note "  $line"; done <<<"$accounts"
  fi
fi
if [[ -z "$CLOUDFLARE_ACCOUNT_ID" ]]; then
  open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
  step "Workers & Pages → the Account ID in the right-hand column."
  ask CLOUDFLARE_ACCOUNT_ID "Paste the account ID:"
fi
env_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
BETTER_AUTH_URL="https://$API_HOST"
say "The API will live at $BETTER_AUTH_URL. The first deploy makes its DNS record and certificate."
note "If $API_HOST already has a DNS record, delete it in Cloudflare first, or the deploy can't claim it."
env_var BETTER_AUTH_URL "$BETTER_AUTH_URL"
pause

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Neon: the production database"
say "This uses Anton's Neon project. Ask him to invite you if you can't see it."
open_url "https://console.neon.tech/app/projects"
step "Open the project. Under Branches, make a branch named 'production' from main if there isn't one."
step "Project dashboard → Connect → Branch: production."
step "Turn 'Connection pooling' ON and copy the string (its host contains -pooler)."
DATABASE_URL=""
secret_or_keep DATABASE_URL "Paste the pooled URL (for the Worker):"
if [[ -n "$DATABASE_URL" && "$DATABASE_URL" != *-pooler* ]]; then
  warn "That host has no -pooler in it. The Worker needs the pooled one."
  confirm "Save it anyway?" || exit 1
fi
[[ -n "$DATABASE_URL" ]] && env_secret DATABASE_URL "$DATABASE_URL"
step "Now turn 'Connection pooling' OFF and copy that string."
DIRECT_DATABASE_URL=""
secret_or_keep DIRECT_DATABASE_URL "Paste the direct URL (for migrations):"
[[ -n "$DIRECT_DATABASE_URL" ]] && env_secret DIRECT_DATABASE_URL "$DIRECT_DATABASE_URL"
pause

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Better Auth: the session signing secret"
if has_secret BETTER_AUTH_SECRET; then
  say "There is one already. Making a new one signs everybody out."
  if confirm "Make a new one?"; then
    env_secret BETTER_AUTH_SECRET "$(openssl rand -base64 32)"
  fi
else
  say "Making a new random one. Nobody needs to see it."
  env_secret BETTER_AUTH_SECRET "$(openssl rand -base64 32)"
fi
pause

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "R2: the bucket for photos and videos"
open_url "https://dash.cloudflare.com/$CLOUDFLARE_ACCOUNT_ID/r2/overview"
step "Create bucket. Name: $BUCKET_DEFAULT (or skip this if it exists)."
step "Location: Provide a location hint → Oceania (OC). Storage class: Standard."
step "Leave public access off. The bucket stays private."
R2_BUCKET=""
default_bucket=$(current_var R2_BUCKET)
ask R2_BUCKET "Bucket name [${default_bucket:-$BUCKET_DEFAULT}]:" || true
R2_BUCKET="${R2_BUCKET:-${default_bucket:-$BUCKET_DEFAULT}}"
env_var R2_BUCKET "$R2_BUCKET"
pause

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "R2: keys for that bucket alone"
open_url "https://dash.cloudflare.com/$CLOUDFLARE_ACCOUNT_ID/r2/api-tokens"
step "Create Account API token. Name it fatigue-api-media."
step "Permissions: Object Read & Write. Apply to specific buckets only → $R2_BUCKET."
step "Create, then copy the Access Key ID and the Secret Access Key (the secret is shown once)."
R2_ACCESS_KEY_ID=""
R2_SECRET_ACCESS_KEY=""
secret_or_keep R2_ACCESS_KEY_ID "Paste the Access Key ID:"
secret_or_keep R2_SECRET_ACCESS_KEY "Paste the Secret Access Key:"
if [[ -n "$R2_ACCESS_KEY_ID" && -n "$R2_SECRET_ACCESS_KEY" ]]; then
  status=$(r2_status)
  if [[ "$status" == 200 ]]; then
    printf '  %s✓%s the keys can read %s\n' "$GREEN" "$RESET" "$R2_BUCKET"
  else
    warn "Listing $R2_BUCKET with these keys answered $status. Check the bucket name and the token's buckets."
    confirm "Save them anyway?" || exit 1
  fi
  env_secret R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
  env_secret R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
elif [[ -n "$R2_ACCESS_KEY_ID$R2_SECRET_ACCESS_KEY" ]]; then
  warn "Only one of the two keys changed. They come as a pair, so neither was saved."
  SKIPPED+=("R2 keys: run this again and paste both")
fi
pause

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Resend: a sending domain"
say "Emails go from a subdomain, so Fatigue's mail stays apart from the main domain's."
open_url "https://resend.com/domains"
step "Add domain → e.g. mail.fatigue.agroupforcoders.com. Region: the closest to you (Tokyo for NZ)."
step "Add the DNS records it shows. If the domain is on Cloudflare, use its Cloudflare auto-configure"
step "button; otherwise add each one under Cloudflare → DNS → Records."
step "Click verify and wait until the domain says Verified. It usually takes a few minutes."
current_from=$(current_var EMAIL_FROM)
[[ -n "$current_from" ]] && note "Currently sending as: $current_from"
MAIL_DOMAIN=""
ask MAIL_DOMAIN "The verified domain${current_from:+ (Enter keeps the current sender)}:" || true
if [[ -n "$MAIL_DOMAIN" ]]; then
  env_var EMAIL_FROM "Fatigue <no-reply@$MAIL_DOMAIN>"
elif [[ -z "$current_from" ]]; then
  SKIPPED+=("EMAIL_FROM: run this again once the Resend domain is verified")
fi
pause

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Resend: an API key"
open_url "https://resend.com/api-keys"
step "Create API key. Name: fatigue-api. Permission: Sending access. Domain: the one you just verified."
step "Copy the key (it's shown once)."
RESEND_API_KEY=""
secret_or_keep RESEND_API_KEY "Paste the key:"
[[ -n "$RESEND_API_KEY" ]] && env_secret RESEND_API_KEY "$RESEND_API_KEY"
pause

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Deploy"
say "Merging the deploy-setup pull request deploys on its own. If it's merged already,"
say "this can start a deploy now. It migrates the production database, then uploads the Worker."
if confirm "Start the Deploy API workflow on main now?"; then
  gh workflow run deploy-api.yml --repo "$REPO" --ref main
  printf '  %s✓%s started. Watch it with: gh run watch --repo %s\n' "$GREEN" "$RESET" "$REPO"
fi
note "Once it's green: curl $BETTER_AUTH_URL/health"

finish
}

run_wizard "$@"; exit
